```python
import json
def calculate_reliability(json_data):
    # Parse the JSON data
    data = json.loads(json_data)

    # Calculate the reliability score based on past and current behavior
    reliability_score = 0
    for event in data['past_events']:
        if event['completed_successfully']:
            reliability_score += event['reliability_points']
        else:
            reliability_score -= event['reliability_points']

    if data['current_event']['completed_successfully']:
        reliability_score += data['current_event']['reliability_points']
    else:
        reliability_score -= data['current_event']['reliability_points']

    # Determine if the person is reliable based on their score
    if reliability_score >= 0:
        return True
    else:
        return False
```
