````python
def find_property(data, prop_name, prop_value):
    results = []
    path = []

    def traverse_object(obj, path):
        if isinstance(obj, dict):
            for k, v in obj.items():
                path.append(str(k))
                traverse_object(v, path)
                path.pop()
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                path.append(str(i))
                traverse_object(v, path)
                path.pop()
        else:
            if str(obj) == str(prop_value):
                results.append({"name": prop_name, "value": str(obj), "path": "/".join(path)})

    traverse_object(data, path)
    return results
