def getRange(minimum, maximum):
    # Step 1: Create an empty list to store the numbers within the given range
    range_list = []

    # Step 2: Determine the sign of the range (positive or negative)
    if minimum < 0 and maximum < 0:
        # Step 3: If both minimum and maximum are negative, iterate from minimum to maximum (inclusive) and add each number to the range list
        for num in range(minimum, maximum - 1, -1):
            range_list.append(num)
    elif minimum < 0 and maximum >= 0:
        # Step 4: If minimum is negative and maximum is non-negative, iterate from minimum to 0 (inclusive) and add each number to the range list
        for num in range(minimum, 0):
            range_list.append(num)
        # Step 5: Iterate from 0 to maximum (inclusive) and add each number to the range list
        for num in range(0, maximum + 1):
            range_list.append(num)
    else:
        # Step 6: If minimum and maximum are both non-negative, iterate from minimum to maximum (inclusive) and add each number to the range list
        for num in range(minimum, maximum + 1):
            range_list.append(num)

    # Step 7: Return the range list
    return range_list

